    { r1: RADII.tripleInner * R, r2: RADII.tripleOuter * R, kind: 'ring' },
    { r1: RADII.tripleOuter * R, r2: RADII.doubleInner * R, kind: 'single' },
    { r1: RADII.doubleInner * R, r2: R, kind: 'ring' }
